-- c006-v001: وہ بچو فرمانبرداری–کرو اُن والدین تمہارے میں خداوند یہ کیونکہ ہے صحیح
-- c006-v002: عزت–کر وہ باپ تیرے اور وہ ماں جو ہے حکم پہلا میں وعدے
-- c006-v003: تاکہ بھلا تجھے ہو اور رہے دیر–عمر پر اُس زمین
-- c006-v004: اور وہ باپو نہ غصہ–دلاؤ وہ بچوں تمہارے بلکہ پرورش–کرو اُنہیں میں تربیت اور نصیحت خداوند–کی
-- c006-v005: وہ غلامو فرمانبرداری–کرو اُن کے–مطابق جسم مالکوں ساتھ خوف اور کانپنے میں صاف–دلی کے دل تمہارے جیسے اُس مسیح
-- c006-v006: نہ کے–مطابق آنکھ–کی–غلامی جیسے آدمیوں–کو–خوش–کرنے–والے بلکہ جیسے غلام مسیح–کے کرتے–ہوئے وہ مرضی کے خدا سے جان
-- c006-v007: ساتھ نیک–خواہی خدمت–کرتے–ہوئے جیسے اُس خداوند اور نہیں انسانوں
-- c006-v008: جانتے–ہوئے کہ ہر–ایک اگر کچھ کرے اچھا یہ پائے–گا سے خداوند خواہ غلام خواہ آزاد
-- c006-v009: اور وہ مالکو وہ وہی کرو کی–طرف اُن چھوڑتے–ہوئے وہ دھمکی جانتے–ہوئے کہ بھی اُن–کا اور تمہارا وہ خداوند ہے میں آسمانوں اور طرفداری نہیں ہے پاس اُس–کے
-- c006-v010: آخر–میں باقی مضبوط–ہو میں خداوند اور میں اُس طاقت کے قوت اُس–کی
-- c006-v011: پہنو وہ زرہ کے خدا کے–لیے اُس قادر–ہونے–کو تم کھڑے–ہونے–کو کے–خلاف اُن چالوں کے شیطان
-- c006-v012: کہ نہیں ہے ہمیں وہ کشتی کے–خلاف خون اور جسم بلکہ کے–خلاف اُن حکومتوں کے–خلاف اُن اختیاروں کے–خلاف اُن دنیا–کے–حکمرانوں کے اندھیرے اِس کے–خلاف اُن روحانی کے بدی میں اُن آسمانی–جگہوں
-- c006-v013: اِس–لیے اِس اُٹھاؤ وہ زرہ کے خدا تاکہ قادر–ہو مقابلہ–کرنے–کو میں اُس دن اُس بُرے اور سب کر–کے کھڑے–ہو
-- c006-v014: کھڑے–رہو پس باندھ–کر وہ کمر تمہاری میں سچائی اور پہن–کر وہ بکتر کے راستبازی
-- c006-v015: اور پہنا–کر اُن پاؤں میں تیاری کے خوشخبری کے سلامتی
-- c006-v016: میں سب اُٹھا–کر وہ ڈھال کے ایمان میں جس قادر–ہو–گے تمام وہ تیر کے شریر وہ جلتے–ہوئے بجھانے–کو
-- c006-v017: اور وہ خود کے نجات لو اور وہ تلوار کے روح جو ہے کلام خدا–کا
-- c006-v018: کے–ذریعے ہر دعا اور منت دعا–کرتے–ہوئے میں ہر وقت میں روح اور کے–لیے اِسی جاگتے–رہو میں پوری استقلال اور منت کے–لیے تمام اُن مقدسوں
-- c006-v019: اور کے–لیے میرے تاکہ مجھے دیا–جائے کلام میں کھولنے کے منہ میرے میں دلیری ظاہر–کرنے–کو وہ بھید کے خوشخبری
-- c006-v020: کے–لیے جس سفیری–کرتا–ہوں میں زنجیر تاکہ میں اُس دلیری–سے–بولوں جیسے چاہیے مجھے بولنے–کو
-- c006-v021: تاکہ لیکن جانو بھی تم وہ کے–مطابق میرے کیا کرتا–ہوں سب بتائے–گا تمہیں تخکس وہ پیارا بھائی اور ایماندار خادم میں خداوند
-- c006-v022: جسے بھیجا کی–طرف تمہاری کے–لیے اِسی اِس تاکہ جانو وہ کے–بارے–میں ہمارے اور تسلی–دے اُن دلوں تمہارے
-- c006-v023: سلامتی اُن بھائیوں اور محبت ساتھ ایمان سے خدا باپ اور خداوند یسوع مسیح
-- c006-v024: وہ فضل ساتھ تمام اُن محبت–کرنے–والوں وہ خداوند ہمارے یسوع مسیح میں بقا

